<section class="container section"><div class="page-head"><div><p class="overline">TUYỂN SINH / ĐIỂM CHUẨN</p><h1>Xác định điểm chuẩn</h1><p class="muted">Dựa trên điểm thi hợp lệ, nguyện vọng, chỉ tiêu và kết quả xếp hạng dự kiến.</p></div></div>
<form method="get" action="<?=e(url('quan-tri/diem-chuan'))?>" class="filter-bar"><label>Kỳ tuyển sinh<select name="exam_id" onchange="this.form.submit()"><option value="0">-- Chọn kỳ --</option><?php foreach($exams as $e):?><option value="<?=$e['id']?>" <?=$exam==$e['id']?'selected':''?>><?=e($e['code'])?></option><?php endforeach;?></select></label><button class="btn btn-light">Xem</button></form>
<?php if($warnings):?><div class="alert warning spaced">Dữ liệu chưa đầy đủ hoặc đang có đồng điểm ranh giới: chưa xác nhận điểm chuẩn. <?=e(implode(' | ',$warnings))?></div><?php endif;?>
<div class="two-col spaced"><section class="card"><h2>Đề xuất theo trường / nguyện vọng</h2><p class="muted">Mức đề xuất = điểm thấp nhất của nhóm được xếp trúng tuyển dự kiến. Không phải mức chuẩn thực tế do cơ quan nhà nước ban hành.</p><div class="table-wrap"><table><thead><tr><th>Trường</th><th>Chỉ tiêu</th><th>NV1</th><th>NV2</th><th>NV3</th></tr></thead><tbody><?php foreach($quotas as $q):?><tr><td><?=e($q['name'])?></td><td><?=$q['seats']?></td><?php foreach([1,2,3] as $pr):?><td><?=e($suggestions[$q['school_id'].':'.$pr]??'—')?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><h2>Điều chỉnh / xác nhận điểm chuẩn</h2><form class="stack" method="post" action="<?=e(url('quan-tri/diem-chuan/luu'))?>" onsubmit="return confirm('Xác nhận mức điểm và căn cứ đã kiểm tra?')"><?=field('cutoff-save')?><input type="hidden" name="exam_id" value="<?=$exam?>"><label>Trường THPT<select name="school_id"><?php foreach($quotas as $q):?><option value="<?=$q['school_id']?>"><?=e($q['name'])?></option><?php endforeach;?></select></label><label>Nguyện vọng<select name="priority"><option value="1">NV1</option><option value="2">NV2</option><option value="3">NV3</option></select></label><label>Mức điểm xét tuyển<input type="number" min="0" max="999" step="0.01" name="threshold" required placeholder="Ví dụ: 27"></label><button class="btn btn-main" <?=$warnings?'disabled':''?>>Xác nhận điểm chuẩn</button></form><p class="hint">Sau khi thay đổi mức điểm, quay lại Xét tuyển để tính dự kiến mới. Bản dự kiến trước sẽ không được dùng để lưu.</p></section></div>
<section class="card spaced"><h2>Các mức đã xác nhận</h2><div class="table-wrap"><table><thead><tr><th>Trường</th><th>Nguyện vọng</th><th>Điểm</th><th>Ngày xác nhận</th></tr></thead><tbody><?php foreach($saved as $r):?><tr><td><?=e($r['school_name'])?></td><td>NV<?=$r['priority']?></td><td><b><?=e($r['threshold'])?></b></td><td><?=e($r['confirmed_at'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$saved):?><p class="empty">Chưa có mức điểm chuẩn nào được xác nhận.</p><?php endif;?></div></section></section>
